package com.github.nyabanban.fuji.emulator.components.sdhost

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import java.nio.file.Path
import kotlin.test.*

class SdControlHostTest {
 private fun input():Map<String,Any> = mapOf("schema" to 1,"profile" to SdHostFactory.CONTROL_PROFILE,"initialRegisters" to (0..1).associate{it.toString() to linkedMapOf("word80" to 0xa55a0005L,"control623e" to 0x55aaL,"mixed6078" to 0xa55a0005L,"control403e" to 0xaa55L,"word60ec" to 0xffffffffL)})
 private class Context(var data:Map<String,Any>):ComponentContext {
  var tick=1L;val entries=mutableMapOf<String,Any>();override val directory=Path.of("unused-sd-controls")
  override val clock=EmulationClock{tick}
  override val ports=object:Ports{override fun<T:Any>register(owner:String,name:String,type:Class<T>,port:T){check(entries.putIfAbsent(name,port)==null)};override fun<T:Any>find(name:String,type:Class<T>):T?=entries[name]?.let{type.cast(it)};override fun removeOwner(owner:String)=error("unexpected remove")}
  override val events=object:EventChannel{override fun publish(event:ComponentEvent)=error("no invented IRQ");override fun subscribe(listener:(ComponentEvent)->Unit):AutoCloseable=error("no subscriptions")}
  override fun dataPath(relative:String)=directory.resolve(relative)
  override fun readData(relative:String)=data
 }
 private fun create(c:Context):HardwareComponent {val f=SdHostFactory();return f.create(c,f.descriptor.settings.associate{it.key to it.default}+mapOf("profile" to SdHostFactory.CONTROL_PROFILE,"inputFile" to "input.yaml"))}
 private fun port(c:Context,s:Int,f:Int)=c.ports.find(SdControlHost.port(s,f),MmioDevice::class.java)!!
 @Test fun explicitAllFieldsFreezeAndIndependentSlotsLanesAndContext(){val data=input();val c=Context(data);c.entries["cpu.execution-location"]=ExecutionLocationSource{ExecutionLocation(3,0x5afb0)};val h=create(c);h.start();val before=h.state()["registers"];for(s in 0..1){port(c,s,2).write(0,2,0xffff);assertEquals(0xa55affffL,port(c,s,2).read(0,4));port(c,s,1).write(0,2,0);assertEquals(0L,port(c,s,1).read(0,2));port(c,s,4).write(0,4,1)};assertEquals(10,h.additionalMmioPorts().size);assertEquals(10,c.entries.values.filterIsInstance<MmioDevice>().map{it.clockIndex}.toSet().size);assertTrue(c.entries.values.filterIsInstance<MmioDevice>().all{it.clockOrder==85});assertEquals(before,h.state()["initialRegisters"]);assertEquals(false,h.state()["cardProtocolQualified"]);assertTrue(h.interruptRoutes().isEmpty());val last=(h.state()["accesses"]as List<*>).last()as Map<*,*>;assertEquals(3,last["core"]);assertEquals(0x5afb0L,last["pcVirtual"])}
 @Test fun missingMalformedOverflowAndAliasesRefuseBeforePublishing(){val base=input();val raw=base["initialRegisters"]as Map<*,*>;val slot=raw["0"]as Map<*,*>;val invalid=mutableListOf<Map<String,Any>>();for(k in base.keys)invalid+=base-k;invalid+=base+mapOf("schema" to 1.0);invalid+=base+mapOf("unexpected" to 1);invalid+=base+mapOf("initialRegisters" to (raw-"1"));for(k in SdControlHost.fields)invalid+=base+mapOf("initialRegisters" to (raw+mapOf("0" to(slot-k))));for((k,v)in listOf("word80" to -1L,"word80" to 0x100000000L,"control623e" to 65536L,"control403e" to 1.0,"mixed6078" to "0","word60ec" to true))invalid+=base+mapOf("initialRegisters" to(raw+mapOf("0" to(slot+mapOf(k to v)))));for(data in invalid){val c=Context(data);assertFails{create(c)};assertTrue(c.entries.isEmpty())};for(s in 0..1)for(f in 0..4){val c=Context(base);c.entries[SdControlHost.port(s,f)]=object:MmioDevice{override fun read(offset:Long,size:Int)=0L;override fun write(offset:Long,size:Int,value:Long){}};assertFails{create(c)};assertEquals(1,c.entries.size)}}
 @Test fun everyUnsupportedWidthDirectionOffsetAndValueIsAtomic(){val c=Context(input());val h=create(c);val before=h.state();for(s in 0..1)for(f in 0..4){val p=port(c,s,f);val rw=if(f==1||f==3)2 else 4;val ww=if(f==2)2 else rw;for(w in listOf(0,1,2,4,8)) {if(w!=rw||f==4){assertFails{p.read(0,w)};assertEquals(before,h.state())};if(w!=ww){assertFails{p.write(0,w,0)};assertEquals(before,h.state())}};for(off in listOf(-1L,1L,2L,4L)){assertFails{p.read(off,rw)};assertFails{p.write(off,ww,0)};assertEquals(before,h.state())};for(value in listOf(-1L,if(ww==2)65536L else 0x100000000L)){assertFails{p.write(0,ww,value)};assertEquals(before,h.state())}}}
 @Test fun clockAndLocationFailuresPrecedeMutationAndCounters(){val c=Context(input());val h=create(c);val before=h.state();c.tick=-1;assertFails{port(c,0,1).write(0,2,1)};assertFails{port(c,0,2).read(0,4)};assertEquals(before,h.state());c.tick=1;c.entries["cpu.execution-location"]=ExecutionLocationSource{error("location failed")};assertFails{port(c,1,2).write(0,2,7)};assertFails{port(c,0,3).read(0,2)};assertEquals(before,h.state())}
 @Test fun inputMutationSnapshotsRingLifecycleAndRestart(){val fields=(input()["initialRegisters"]as Map<*,*>)["0"]as Map<*,*>;val mutable=fields.entries.associate{it.key.toString() to it.value!!}.toMutableMap();val c=Context(input()+mapOf("initialRegisters" to mapOf("0" to mutable,"1" to fields)));val h=create(c);val initial=h.state()["initialRegisters"];mutable["word80"]=0;assertEquals(initial,h.state()["initialRegisters"]);repeat(300){port(c,0,0).write(0,4,it.toLong())};assertEquals(300L,h.state()["accessCount"]);assertEquals(256,(h.state()["accesses"]as List<*>).size);assertEquals(true,h.state()["accessLogTruncated"]);h.applySettings(mapOf("profile" to SdHostFactory.CONTROL_PROFILE));assertFails{h.applySettings(mapOf("inputFile" to "other.yaml"))};h.close();h.close();assertFails{h.start()};for(s in 0..1)for(f in 0..4){assertFails{port(c,s,f).read(0,if(f==1||f==3)2 else 4)};assertFails{port(c,s,f).write(0,if(f==1||f==2||f==3)2 else 4,0)}}}
}
